class Solution {
    public int[] squaredOffsets(int[] offsets) {
        // Squaring breaks order (negatives flip), so sort after squaring
        // O(n log n)
        int[] out = new int[offsets.length];
        for (int i = 0; i < offsets.length; i++) out[i] = offsets[i] * offsets[i];
        Arrays.sort(out);
        return out;
    }
}

