class Solution {
public:
    vector<int> squaredOffsets(vector<int>& offsets) {
        // Squaring breaks order (negatives flip), so sort after squaring
        // O(n log n)
        vector<int> out;
        for (int x : offsets) out.push_back(x * x);
        sort(out.begin(), out.end());
        return out;
    }
};

