class Solution {
    public int minSpeed(int[] jobs, int hours) {
        // Binary search speed (faster speed never needs more hours)
        // Hours at speed = sum of ceil(job / speed)
        // Smallest speed that fits hours = first feasible speed
        // speeds 1 to max(jobs) (one hour per job, no faster speed helps)
        int lo = 1, hi = 1;
        for (int j : jobs) hi = Math.max(hi, j);
        while (lo < hi) {
            // middle, rounded down (lo + (hi - lo) avoids int overflow)
            int mid = lo + (hi - lo) / 2;
            // hours at mid (long, sum can pass int range)
            long need = 0;
            // partly done job still uses full hour
            for (int j : jobs) need += (j + (long) mid - 1) / mid;
            // fits, so mid could be answer (hi = mid, not mid - 1)
            if (need <= hours) hi = mid;
            // too slow, so answer is faster (lo = mid + 1)
            else lo = mid + 1;
        }
        return lo;
    }
}

