class Solution {
    public int minSpeed(int[] jobs, int hours) {
        // Binary search speed (faster speed never needs more hours)
        // Hours at speed = sum of ceil(job / speed)
        // Smallest speed that fits hours = first feasible speed
        // biggest job (one hour per job, so no faster speed helps)
        int biggest = 0;
        for (int i = 0; i < jobs.length; i++) {
            if (jobs[i] > biggest) {
                biggest = jobs[i];
            }
        }
        int low = 1;
        int high = biggest;
        while (low < high) {
            // middle, rounded down (low + (high - low) avoids int overflow)
            int speed = low + (high - low) / 2;
            // hours at this speed (long, sum can pass int range)
            long needed = 0;
            for (int i = 0; i < jobs.length; i++) {
                int job = jobs[i];
                int jobHours = job / speed;
                if (job % speed != 0) {
                    // leftover pages still use full hour
                    jobHours = jobHours + 1;
                }
                needed = needed + jobHours;
            }
            if (needed <= hours) {
                // fits, so speed could be answer (high = speed, not speed - 1)
                high = speed;
            } else {
                // too slow, so answer is faster (low = speed + 1)
                low = speed + 1;
            }
        }
        return low;
    }
}

