class Solution:
    def minStickers(self, scores: List[int]) -> int:
        # Raise stickers until no higher-scored kid ties or trails neighbour
        # Sweep repeatedly, stop when full sweep changes nothing
        # Every bump is forced (values only rise), so stable result is minimal
        n = len(scores)
        # give[i] (current stickers for kid i; 1 = at least one each)
        give = [1] * n
        changed = True
        # another sweep while last one changed something
        while changed:
            changed = False
            for i in range(n):
                # must beat left neighbour, so go one above it
                if i > 0 and scores[i] > scores[i - 1] and give[i] <= give[i - 1]:
                    give[i] = give[i - 1] + 1
                    changed = True
                # must beat right neighbour, so go one above it
                if i < n - 1 and scores[i] > scores[i + 1] and give[i] <= give[i + 1]:
                    give[i] = give[i + 1] + 1
                    changed = True
        return sum(give)

