        boolean changed = true;
        // another sweep while last one changed something
        while (changed) {
            changed = false;
            for (int i = 0; i < n; i++) {
                // must beat left neighbour, so go one above it
                if (i > 0 && scores[i] > scores[i - 1] && give[i] <= give[i - 1]) { give[i] = give[i - 1] + 1; changed = true; }
