                if (i < n - 1 && scores[i] > scores[i + 1] && give[i] <= give[i + 1]) { give[i] = give[i + 1] + 1; changed = true; }
            }
        }
        int total = 0;
        for (int g : give) total += g;
        return total;
    }
}

